param(
    [switch]$Stop,
    [switch]$NoBrowser,
    [ValidateRange(1024, 65535)]
    [int]$LocalPort = 8765
)

$ErrorActionPreference = 'Stop'

$SshExe = Join-Path $env:WINDIR 'System32\OpenSSH\ssh.exe'
$KeyFile = Get-ChildItem -LiteralPath 'C:\Users\hzq00\Downloads\pi-agent\VPS' -Recurse -File -Filter 'k3_p4_fable_ed25519_PRIVATE_KEY.txt' -ErrorAction SilentlyContinue | Select-Object -First 1
if (-not $KeyFile) {
    throw 'Could not find k3_p4_fable_ed25519_PRIVATE_KEY.txt below C:\Users\hzq00\Downloads\pi-agent\VPS.'
}
$KeyPath = $KeyFile.FullName
$KnownHostsPath = 'C:\Users\hzq00\Documents\Codex\2026-08-09\google-cloud-shell-gcloud-k3-p4\work\filebrowser-runtime\known_hosts'
$RemoteHost = 'k3@136.85.49.91'
$ForwardSpec = "127.0.0.1:${LocalPort}:127.0.0.1:8080"
$Url = "http://127.0.0.1:${LocalPort}"

function Get-K3TunnelProcess {
    @(Get-CimInstance Win32_Process -Filter "Name = 'ssh.exe'" -ErrorAction SilentlyContinue | Where-Object {
        $_.CommandLine -like "*$ForwardSpec*" -and $_.CommandLine -like "*$RemoteHost*"
    })
}

if ($Stop) {
    $processes = Get-K3TunnelProcess
    if ($processes.Count -eq 0) {
        Write-Host 'K3 File Browser SSH tunnel is not running.'
        exit 0
    }

    $processes | ForEach-Object { Stop-Process -Id $_.ProcessId -Force }
    Write-Host "Stopped K3 File Browser SSH tunnel (PID: $($processes.ProcessId -join ', '))."
    exit 0
}

foreach ($requiredPath in @($SshExe, $KeyPath, $KnownHostsPath)) {
    if (-not (Test-Path -LiteralPath $requiredPath -PathType Leaf)) {
        throw "Required SSH file does not exist: $requiredPath"
    }
}

$listener = Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $LocalPort -State Listen -ErrorAction SilentlyContinue
if ($listener) {
    $tunnel = Get-K3TunnelProcess
    if ($tunnel.Count -eq 0 -or $listener.OwningProcess -notin $tunnel.ProcessId) {
        throw "Local port 127.0.0.1:$LocalPort is occupied by another process (PID: $($listener.OwningProcess -join ', '))."
    }
} else {
    $sshArguments = @(
        '-F', 'NUL',
        '-4',
        '-N', '-T',
        '-L', $ForwardSpec,
        '-i', $KeyPath,
        '-o', 'BatchMode=yes',
        '-o', 'IdentitiesOnly=yes',
        '-o', 'IdentityAgent=none',
        '-o', 'AddKeysToAgent=no',
        '-o', 'PreferredAuthentications=publickey',
        '-o', 'PasswordAuthentication=no',
        '-o', 'KbdInteractiveAuthentication=no',
        '-o', 'GlobalKnownHostsFile=NUL',
        '-o', 'UpdateHostKeys=no',
        '-o', 'ExitOnForwardFailure=yes',
        '-o', 'ConnectTimeout=10',
        '-o', 'ConnectionAttempts=1',
        '-o', 'ServerAliveInterval=30',
        '-o', 'ServerAliveCountMax=3',
        '-o', "UserKnownHostsFile=$KnownHostsPath",
        '-o', 'StrictHostKeyChecking=yes',
        $RemoteHost
    )

    $sshProcess = Start-Process -FilePath $SshExe -ArgumentList $sshArguments -WindowStyle Hidden -PassThru

    $deadline = (Get-Date).AddSeconds(12)
    do {
        if ($sshProcess.HasExited) {
            throw "SSH tunnel exited before becoming ready (exit code: $($sshProcess.ExitCode))."
        }
        Start-Sleep -Milliseconds 200
        $listener = Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $LocalPort -State Listen -ErrorAction SilentlyContinue
    } until ($listener -or (Get-Date) -ge $deadline)

    if (-not $listener) {
        Stop-Process -Id $sshProcess.Id -Force -ErrorAction SilentlyContinue
        throw 'SSH tunnel did not become ready within 12 seconds.'
    }
}

$response = Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 8
if ($response.StatusCode -ne 200) {
    throw "File Browser returned unexpected HTTP status $($response.StatusCode)."
}

Write-Host "K3 File Browser is ready: $Url"
Write-Host 'Run this script with -Stop to close the SSH tunnel.'

if (-not $NoBrowser) {
    Start-Process $Url
}

param(
    [ValidateRange(1024, 65535)]
    [int]$LocalPort = 8766,
    [switch]$Stop
)

$ErrorActionPreference = 'Stop'
$OpenScript = Join-Path $PSScriptRoot 'open-k3-filebrowser.ps1'
$LogDirectory = Join-Path $PSScriptRoot 'runtime'
$LogPath = Join-Path $LogDirectory "filebrowser-tunnel-$LocalPort.log"
$ForwardSpec = "127.0.0.1:${LocalPort}:127.0.0.1:8080"
$SupervisorPattern = "watch-k3-filebrowser.ps1*LocalPort*$LocalPort"

function Get-SupervisorProcesses {
    @(Get-CimInstance Win32_Process -Filter "Name = 'powershell.exe' OR Name = 'pwsh.exe'" -ErrorAction SilentlyContinue | Where-Object {
        $_.ProcessId -ne $PID -and $_.CommandLine -like "*$SupervisorPattern*"
    })
}

function Write-TunnelLog([string]$Message) {
    New-Item -ItemType Directory -Force -Path $LogDirectory | Out-Null
    $line = "$(Get-Date -Format o) $Message"
    Add-Content -LiteralPath $LogPath -Value $line -Encoding UTF8
}

if ($Stop) {
    $supervisors = Get-SupervisorProcesses
    foreach ($process in $supervisors) {
        Stop-Process -Id $process.ProcessId -Force -ErrorAction SilentlyContinue
    }
    Write-Host "Stopped K3 File Browser tunnel supervisor for port $LocalPort."
    exit 0
}

if (-not (Test-Path -LiteralPath $OpenScript -PathType Leaf)) {
    throw "Missing tunnel launcher: $OpenScript"
}

$mutex = [Threading.Mutex]::new($false, "Local\K3FileBrowserTunnelSupervisor-$LocalPort")
if (-not $mutex.WaitOne(0)) {
    Write-Host "K3 File Browser tunnel supervisor is already running for port $LocalPort."
    exit 0
}

$delaySeconds = 5
$maximumDelaySeconds = 60
try {
    Write-TunnelLog "SUPERVISOR_START port=$LocalPort"
    while ($true) {
        $listener = Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $LocalPort -State Listen -ErrorAction SilentlyContinue
        if ($listener) {
            $owner = Get-CimInstance Win32_Process -Filter "ProcessId = $($listener.OwningProcess)" -ErrorAction SilentlyContinue
            if ($owner -and $owner.Name -eq 'ssh.exe' -and $owner.CommandLine -like "*$ForwardSpec*") {
                try {
                    $response = Invoke-WebRequest -Uri "http://127.0.0.1:$LocalPort/" -UseBasicParsing -TimeoutSec 4
                    if ($response.StatusCode -eq 200) {
                        $delaySeconds = 5
                    } else {
                        Write-TunnelLog "REMOTE_HTTP_DEGRADED status=$($response.StatusCode) tunnel_pid=$($owner.ProcessId)"
                    }
                } catch {
                    # Keep the SSH process: the remote File Browser may be restarting
                    # while the underlying SSH connection is still healthy.
                    Write-TunnelLog "REMOTE_HTTP_UNAVAILABLE tunnel_pid=$($owner.ProcessId) detail=$($_.Exception.Message)"
                }
                Start-Sleep -Seconds 10
                continue
            }
            Write-TunnelLog "LOCAL_PORT_CONFLICT owner_pid=$($listener.OwningProcess)"
            Start-Sleep -Seconds 30
            continue
        }

        try {
            & $OpenScript -LocalPort $LocalPort -NoBrowser
            Write-TunnelLog "TUNNEL_RECONNECTED port=$LocalPort"
            $delaySeconds = 5
            Start-Sleep -Seconds 10
        } catch {
            Write-TunnelLog "RECONNECT_FAILED delay=$delaySeconds detail=$($_.Exception.Message)"
            Start-Sleep -Seconds $delaySeconds
            $delaySeconds = [Math]::Min($maximumDelaySeconds, $delaySeconds * 2)
        }
    }
} finally {
    Write-TunnelLog "SUPERVISOR_STOP port=$LocalPort"
    $mutex.ReleaseMutex()
    $mutex.Dispose()
}
